// Build one alert line out of the Error Trigger payload.
//
// The trigger hands over one of two shapes (verified against n8n 2.44.6,
// dist/execution-lifecycle/execute-error-workflow.js):
//   a failed execution   -> { execution: { id, url, error, lastNodeExecuted, mode, retryOf }, workflow: { id, name } }
//   a trigger that could not even start -> { trigger: { error, mode }, workflow: { id, name } }
// Both carry `workflow`, only one carries `execution`, so everything below is read defensively.
//
// No network and no process env in here: this kit blocks both in Code nodes
// (N8N_BLOCK_ENV_ACCESS_IN_NODE=true, and the runner sandbox has no egress of its own).
// Formatting happens here, sending happens in the next node.
const data = $input.first().json;
const execution = data.execution ?? {};
const trigger = data.trigger ?? {};
const workflow = data.workflow ?? {};
const error = execution.error ?? trigger.error ?? {};
const kind = data.execution ? 'execution' : 'trigger';

// Telegram sends plain text here on purpose: no parse_mode, so an error message containing
// _ * ` or [ cannot turn the alert itself into a 400 from the Telegram API.
const oneLine = (value, max) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const nodeName = oneLine(error.node?.name ?? error.node, 80) || oneLine(execution.lastNodeExecuted, 80);
const message = oneLine(error.message ?? error.description, 400) || 'no error message';
const workflowName = oneLine(workflow.name, 80) || 'unknown workflow';

const lines = [`n8n FAILED: ${workflowName}`];
if (nodeName) lines.push(`node: ${nodeName}`);
lines.push(`error: ${message}`);
if (kind === 'execution') {
  const retry = execution.retryOf ? ` (retry of ${execution.retryOf})` : '';
  lines.push(`execution ${execution.id ?? '?'}${retry}, mode ${execution.mode ?? '?'}`);
  if (execution.url) lines.push(String(execution.url));
} else {
  lines.push(`the trigger could not start (mode ${trigger.mode ?? '?'}) - nothing ran`);
}

return [
  {
    json: {
      kind,
      workflowId: workflow.id ?? null,
      workflowName: workflow.name ?? null,
      executionId: execution.id ?? null,
      executionUrl: execution.url ?? null,
      nodeName: nodeName || null,
      errorName: error.name ?? null,
      message,
      mode: execution.mode ?? trigger.mode ?? null,
      retryOf: execution.retryOf ?? null,
      stack: oneLine(error.stack, 1000) || null,
      text: lines.join('\n'),
    },
  },
];
